function updateCaptureOrbs(dt) {
  for (let i = captureOrbs.length - 1; i >= 0; i--) {
    const o = captureOrbs[i];
    o.t += dt / o.dur;
    o.mesh.rotation.y += dt * 8;
    o.mesh.rotation.z += dt * 5;
    const t = clamp(o.t, 0, 1);
    const arc = Math.sin(t * Math.PI) * 2.2;
