      burst(new THREE.Vector3(r.x, groundAt(r.x, r.z) + 1, r.z), 0xc8f36a, 12, 2, 0.1);
      respawns.splice(i, 1);
    }
  }
  for (let i = hollowRespawns.length - 1; i >= 0; i--) {
