const path = require('node:path');

(async () => {
  const browser = await chromium.launch({
    headless: true,
    args: ['--no-sandbox', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist']
  });
  const page = await browser.newPage({ viewport: { width: 1024, height: 576 } });
  const errors = [];
  const warnings = [];
  page.on('console', m => {
    if (m.type() === 'error') errors.push(m.text());
    if (m.type() === 'warning') warnings.push(m.text());
  });
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
  await page.waitForFunction(() => !!window.__wildline, null, { timeout: 20000 });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: path.join('/home/runner/work/PlayGround/PlayGround', 'screenshots', 'verify_menu.jpg'), type: 'jpeg', quality: 82 });
  await page.click('#startBtn');
  await page.waitForTimeout(1600);
  const initial = await page.evaluate(() => ({
    state: window.__wildline.state,
    hp: window.__wildline.player.health,
    pos: window.__wildline.player.pos.toArray(),
    quest: JSON.parse(JSON.stringify(window.__wildline.quest)),
    cameraMode: document.getElementById('cameraMode').textContent,
    hudHidden: document.getElementById('hud').hidden,
    lockHint: document.getElementById('lockHint').hidden
  }));
  // Move forward and strafe
  await page.keyboard.down('w');
  await page.waitForTimeout(700);
  await page.keyboard.up('w');
  await page.keyboard.down('d');
  await page.waitForTimeout(500);
  await page.keyboard.up('d');
  const moved = await page.evaluate(() => window.__wildline.player.pos.toArray());
  // Fire a shot
  const ammoBefore = await page.evaluate(() => +document.getElementById('ammoMag').textContent);
  await page.mouse.click(512, 288);
  await page.waitForTimeout(250);
  const ammoAfter = await page.evaluate(() => +document.getElementById('ammoMag').textContent);
  // Camera modes
  await page.keyboard.press('c');
  await page.waitForTimeout(600);
  const cam1 = await page.evaluate(() => ({ label: document.getElementById('cameraMode').textContent, playerVisible: window.__wildline.debug.viewScene === window.__wildline.debug.viewScene }));
  await page.screenshot({ path: path.join('/home/runner/work/PlayGround/PlayGround', 'screenshots', 'verify_third.jpg'), type: 'jpeg', quality: 82 });
  await page.keyboard.press('c');
  await page.waitForTimeout(600);
  const cam2 = await page.evaluate(() => ({ label: document.getElementById('cameraMode').textContent }));
  await page.screenshot({ path: path.join('/home/runner/work/PlayGround/PlayGround', 'screenshots', 'verify_second.jpg'), type: 'jpeg', quality: 82 });
  await page.keyboard.press('c');
  await page.waitForTimeout(600);
  const cam0 = await page.evaluate(() => ({ label: document.getElementById('cameraMode').textContent }));
  // Teleport to a scenic spot and take final screenshot
  await page.evaluate(() => { window.__wildline.teleport(28, 46, 2.6); window.__wildline.camera(0); });
  await page.waitForTimeout(1400);
  await page.screenshot({ path: path.join('/home/runner/work/PlayGround/PlayGround', 'screenshots', 'verify_game.jpg'), type: 'jpeg', quality: 82 });
  const final = await page.evaluate(() => ({
    hp: document.getElementById('healthText').textContent,
    state: window.__wildline.state,
    weapon: document.getElementById('weaponName').textContent,
    fpsHint: document.getElementById('timeLabel').textContent,
    damageFlash: getComputedStyle(document.getElementById('damageFlash')).opacity,
    bodyClasses: document.body.className,
    lowHealth: document.body.classList.contains('low-health')
  }));
  console.log(JSON.stringify({ initial, moved, ammoBefore, ammoAfter, cam0, cam1, cam2, final, errors, warnings: warnings.slice(0, 10) }, null, 2));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

