const {chromium}=require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{const b=await chromium.launch({headless:true,args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader','--disable-gpu-compositing']});const p=await b.newPage({viewport:{width:1024,height:576}});const errors=[];p.on('pageerror',e=>errors.push(e.message));p.on('console',m=>{if(m.type()==='error')errors.push(m.text())});await p.goto('http://127.0.0.1:3002/',{waitUntil:'domcontentloaded'});await p.waitForFunction(()=>window.__wildline);await p.evaluate(()=>window.__wildline.start());
const result=await p.evaluate(async()=>{const w=window.__wildline, pos=()=>w.player.pos.toArray();const start=pos();window.dispatchEvent(new KeyboardEvent('keydown',{key:'c'}));window.dispatchEvent(new KeyboardEvent('keyup',{key:'c'}));const camera1=document.querySelector('#cameraMode').textContent;window.dispatchEvent(new KeyboardEvent('keydown',{key:'c'}));window.dispatchEvent(new KeyboardEvent('keyup',{key:'c'}));const camera2=document.querySelector('#cameraMode').textContent;window.dispatchEvent(new KeyboardEvent('keydown',{key:'c'}));window.dispatchEvent(new KeyboardEvent('keyup',{key:'c'}));const camera3=document.querySelector('#cameraMode').textContent;window.dispatchEvent(new KeyboardEvent('keydown',{key:'w'}));await new Promise(r=>setTimeout(r,450));window.dispatchEvent(new KeyboardEvent('keyup',{key:'w'}));return {state:w.state,cameras:[camera1,camera2,camera3],start,end:pos(),hp:w.player.health,ammo:document.querySelector('#ammoMag').textContent}});console.log(JSON.stringify({result,errors},null,2));await b.close()})().catch(e=>{console.error(e);process.exit(1)});
